from __future__ import annotations
from ..ir import ContextKey, Expr, Fragment, InputRef, TaskGraph

def build_transformer_block_task(seq_len: int=2048, hidden_dim: int=4096, heads: int=32, batch_size: int=1, task_id: str='transformer') -> TaskGraph:
    head_dim = max(64, hidden_dim // max(1, heads))
    ff_dim = hidden_dim * 4
    task = TaskGraph(task_id=task_id, task_type='LLM', domain='R', metadata={'seq_len': seq_len, 'hidden_dim': hidden_dim, 'heads': heads, 'batch_size': batch_size})
    qkv = Fragment(fragment_id='qkv_proj', task_type='LLM', stage='IM', expr=Expr.build('matmul_tile', InputRef('tokens', shape=(batch_size, seq_len, hidden_dim), dtype='fp16'), InputRef('w_qkv', shape=(hidden_dim, hidden_dim * 3), dtype='fp16'), template_family='linear_map'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, hidden_dim), delta_t=2000000), estimated_ops=batch_size * seq_len * hidden_dim * 3 // 16, estimated_bytes=batch_size * seq_len * hidden_dim * 6, template_family='linear_map', semantic_group='attn_qkv', metadata={'micro_ops': ['matmul_tile', 'matmul_tile', 'matmul_tile']})
    task.add_fragment(qkv)
    score = Fragment(fragment_id='attn_score', task_type='LLM', stage='IT', expr=Expr.build('matmul_tile', InputRef('q', shape=(batch_size, heads, seq_len, head_dim), dtype='fp16'), InputRef('k', shape=(batch_size, heads, head_dim, seq_len), dtype='fp16'), template_family='linear_map'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, heads, seq_len, head_dim), delta_t=2000000), deps=['qkv_proj'], estimated_ops=batch_size * heads * seq_len * seq_len * head_dim // 128, estimated_bytes=batch_size * heads * seq_len * head_dim * 4, template_family='linear_map', semantic_group='attn_score', metadata={'micro_ops': ['matmul_tile']})
    task.add_fragment(score)
    softmax = Fragment(fragment_id='attn_softmax', task_type='LLM', stage='SC', expr=Expr.build('softmax', InputRef('score', shape=(batch_size, heads, seq_len, seq_len), dtype='fp16'), template_family='reduction'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, heads, seq_len, min(seq_len, 256)), delta_t=2000000), deps=['attn_score'], estimated_ops=batch_size * heads * seq_len * seq_len // 16, estimated_bytes=batch_size * heads * seq_len * seq_len * 2, template_family='reduction', semantic_group='attn_softmax', metadata={'micro_ops': ['layernorm', 'field_reduce']})
    task.add_fragment(softmax)
    context = Fragment(fragment_id='attn_context', task_type='LLM', stage='IT', expr=Expr.build('matmul_tile', InputRef('attn', shape=(batch_size, heads, seq_len, seq_len), dtype='fp16'), InputRef('v', shape=(batch_size, heads, seq_len, head_dim), dtype='fp16'), template_family='linear_map'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, heads, seq_len, head_dim), delta_t=2000000), deps=['attn_softmax'], estimated_ops=batch_size * heads * seq_len * seq_len * head_dim // 128, estimated_bytes=batch_size * heads * seq_len * head_dim * 4, template_family='linear_map', semantic_group='attn_context', metadata={'micro_ops': ['matmul_tile']})
    task.add_fragment(context)
    out_proj = Fragment(fragment_id='attn_out', task_type='LLM', stage='IT', expr=Expr.build('matmul_tile', InputRef('ctx', shape=(batch_size, seq_len, hidden_dim), dtype='fp16'), InputRef('w_o', shape=(hidden_dim, hidden_dim), dtype='fp16'), template_family='linear_map'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, hidden_dim), delta_t=2000000), deps=['attn_context'], estimated_ops=batch_size * seq_len * hidden_dim * hidden_dim // 64, estimated_bytes=batch_size * seq_len * hidden_dim * 2, template_family='linear_map', semantic_group='attn_out', metadata={'micro_ops': ['matmul_tile']})
    task.add_fragment(out_proj)
    resid = Fragment(fragment_id='residual_add', task_type='LLM', stage='SC', expr=Expr.build('add', InputRef('tokens', shape=(batch_size, seq_len, hidden_dim), dtype='fp16'), InputRef('attn_out', shape=(batch_size, seq_len, hidden_dim), dtype='fp16'), template_family='linear_map'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, hidden_dim), delta_t=2000000), deps=['attn_out'], estimated_ops=batch_size * seq_len * hidden_dim, estimated_bytes=batch_size * seq_len * hidden_dim * 2, template_family='linear_map', semantic_group='residual', metadata={'micro_ops': ['field_add']})
    task.add_fragment(resid)
    norm1 = Fragment(fragment_id='norm1', task_type='LLM', stage='SC', expr=Expr.build('layernorm', InputRef('resid', shape=(batch_size, seq_len, hidden_dim), dtype='fp16'), template_family='reduction'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, hidden_dim), delta_t=2000000), deps=['residual_add'], estimated_ops=batch_size * seq_len * hidden_dim * 2, estimated_bytes=batch_size * seq_len * hidden_dim * 2, template_family='reduction', semantic_group='norm1', metadata={'micro_ops': ['layernorm']})
    task.add_fragment(norm1)
    ff1 = Fragment(fragment_id='ff1', task_type='LLM', stage='IT', expr=Expr.build('matmul_tile', InputRef('norm1', shape=(batch_size, seq_len, hidden_dim), dtype='fp16'), InputRef('w_ff1', shape=(hidden_dim, ff_dim), dtype='fp16'), template_family='linear_map'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, hidden_dim), delta_t=2000000), deps=['norm1'], estimated_ops=batch_size * seq_len * hidden_dim * ff_dim // 64, estimated_bytes=batch_size * seq_len * ff_dim * 2, template_family='linear_map', semantic_group='ff1', metadata={'micro_ops': ['matmul_tile']})
    task.add_fragment(ff1)
    gelu = Fragment(fragment_id='ff_gelu', task_type='LLM', stage='SC', expr=Expr.build('gelu', InputRef('ff1', shape=(batch_size, seq_len, ff_dim), dtype='fp16'), template_family='nonlinear_lookup'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, ff_dim), delta_t=2000000), deps=['ff1'], estimated_ops=batch_size * seq_len * ff_dim, estimated_bytes=batch_size * seq_len * ff_dim * 2, template_family='nonlinear_lookup', semantic_group='ff_gelu', metadata={'micro_ops': ['gelu']})
    task.add_fragment(gelu)
    ff2 = Fragment(fragment_id='ff2', task_type='LLM', stage='IT', expr=Expr.build('matmul_tile', InputRef('gelu', shape=(batch_size, seq_len, ff_dim), dtype='fp16'), InputRef('w_ff2', shape=(ff_dim, hidden_dim), dtype='fp16'), template_family='linear_map'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, hidden_dim), delta_t=2000000), deps=['ff_gelu'], estimated_ops=batch_size * seq_len * ff_dim * hidden_dim // 64, estimated_bytes=batch_size * seq_len * hidden_dim * 2, template_family='linear_map', semantic_group='ff2', metadata={'micro_ops': ['matmul_tile']})
    task.add_fragment(ff2)
    norm2 = Fragment(fragment_id='norm2', task_type='LLM', stage='SC', expr=Expr.build('layernorm', InputRef('ff2', shape=(batch_size, seq_len, hidden_dim), dtype='fp16'), template_family='reduction'), context=ContextKey(domain='R', dtype='fp16', layout='tile', tile=(batch_size, seq_len, hidden_dim), delta_t=2000000), deps=['ff2'], estimated_ops=batch_size * seq_len * hidden_dim * 2, estimated_bytes=batch_size * seq_len * hidden_dim * 2, template_family='reduction', semantic_group='norm2', metadata={'micro_ops': ['layernorm']})
    task.add_fragment(norm2)
    task.set_outputs(['norm2'])
    return task

def build_clip_vit_b32_task(batch_size: int=1, task_id: str='clip_vit_b32') -> TaskGraph:
    task = build_transformer_block_task(seq_len=50, hidden_dim=768, heads=12, batch_size=batch_size, task_id=task_id)
    task.metadata.update({'model': 'clip_vit_b32', 'encoder': 'vision+text', 'patch_size': 32, 'image_resolution': 224})
    return task
